def test_coroutine_await_all_small_and_large(scheduler):
    completed = Ref(0)
    n = 70
    flags = [Ref(False) for _ in range(n)]

    def make(i):
        def body():
            co.wait_until(flags[i].get)

        return Command.no_requirements(body).named(f"Child[{i}]")

    children = [make(i) for i in range(n)]

    def parent_body():
        co.await_all(children)
        completed.increment_and_get()

    parent = Command.no_requirements(parent_body).named("Parent")
    scheduler.schedule(parent)
    scheduler.run()
    assert completed.get() == 0 and scheduler.is_running(parent)
    for i in range(64):
        flags[i].set(True)
    scheduler.run()
    assert completed.get() == 0
    for i in range(64, n):
        flags[i].set(True)
    scheduler.run()
    assert completed.get() == 1
    assert not scheduler.is_running(parent)


def test_coroutine_await_any_small_and_large(scheduler):
    finished = Ref(-1)
    n = 80
    flags = [Ref(False) for _ in range(n)]

    def make(i):
        def body():
            co.wait_until(flags[i].get)
            finished.set(i)

        return Command.no_requirements(body).named(f"AnyChild[{i}]")

    children = [make(i) for i in range(n)]

    def parent_body():
        co.await_any(children)

    parent = Command.no_requirements(parent_body).named("ParentAny")
    scheduler.schedule(parent)
    scheduler.run()
    assert finished.get() == -1 and scheduler.is_running(parent)
    flags[75].set(True)
    scheduler.run()
    assert finished.get() == 75
    assert not scheduler.is_running(parent)
    for c in children:
        assert not scheduler.is_running(c)


def test_fork_result_await_completion(scheduler):
    flag1, flag2, done = Ref(False), Ref(False), Ref(False)

    def w1():
        co.wait_until(flag1.get)

    def w2():
        co.wait_until(flag2.get)

    c1 = Command.no_requirements(w1).named("C1")
    c2 = Command.no_requirements(w2).named("C2")

    def parent_body():
        fork_result = co.fork(c1, c2)
        fork_result.await_completion()
        done.set(True)

    scheduler.schedule(Command.no_requirements(parent_body).named("ParentForkAwait"))
    scheduler.run()
    assert not done.get()
    assert scheduler.is_running(c1) and scheduler.is_running(c2)
    flag1.set(True)
    scheduler.run()
    assert not done.get()
    flag2.set(True)
    scheduler.run()
    assert done.get()


