def test_tracker_with_rescheduled_command(scheduler):
    cmd = Command.no_requirements(co.park).named("Rescheduled")
    r1 = scheduler.schedule(cmd)
    scheduler.run()
    assert r1.run_id > 0
    scheduler.cancel(cmd)
    assert scheduler.run_id(cmd) == 0
    r2 = scheduler.schedule(cmd)
    scheduler.run()
    assert r2.run_id > r1.run_id
    assert scheduler.run_id(cmd) == r2.run_id
    t = CommandRunTracker.of(scheduler, [r1])
    assert not t.are_all_running() and not t.is_any_running()


