def test_large_tracker_with_mixed_stale_and_rescheduled_commands(scheduler):
    cmds, initial = _parked(scheduler, 80, "Cmd")
    for i in range(20):
        scheduler.cancel(cmds[i])
    for i in range(20, 40):
        scheduler.cancel(cmds[i])
        scheduler.schedule(cmds[i])
    for i in range(64, 70):
        scheduler.cancel(cmds[i])
    for i in range(70, 75):
        scheduler.cancel(cmds[i])
        scheduler.schedule(cmds[i])
    scheduler.run()
    t = CommandRunTracker.of(scheduler, initial)
    assert not t.are_all_running() and t.is_any_running()
    for i in range(40, 64):
        scheduler.cancel(cmds[i])
    assert t.is_any_running()
    for i in range(75, 80):
        scheduler.cancel(cmds[i])
    assert not t.is_any_running()
    assert not t.are_all_running()
